D={
82001:("Passado simples + contínuo","O **passado contínuo** (*was/were + -ing*) descreve o cenário; o **passado simples** traz o fato que o interrompe.",[("It {{was raining}} when he {{arrived}}.","Estava chovendo quando ele chegou."),("While we {{were talking}}, the lights {{went out}}.","Enquanto conversávamos, as luzes se apagaram."),("{{Suddenly}}, someone {{knocked}} on the door.","De repente, alguém bateu à porta."),("The pilgrims {{were resting}} at the inn.","Os peregrinos descansavam na hospedaria.")],"Qual frase tem uma interrupção?",["I was reading when the phone rang.","I read when the phone was ringing.","I was reading when the phone was ringing."],0,"Cenário em contínuo, interrupção em simples."),
82002:("Past perfect","**Had + particípio** mostra uma ação anterior a outra no passado.",[("When I arrived, he {{had already left}}.","Quando cheguei, ele já tinha saído."),("The man {{hadn't seen}} anything.","O homem não tinha visto nada."),("{{Had you met}} him before?","Você já o tinha conhecido antes?"),("The detective {{had found}} a clue.","O detetive tinha encontrado uma pista.")],"Qual ação veio primeiro? “When she called, I had left.”",["She called.","I left.","Ambas ao mesmo tempo."],1,"Had left = anterior à ligação."),
82003:("Past perfect com before/after","Com **before** e **after**, o past perfect marca o fato mais antigo.",[("After he {{had eaten}}, he went out.","Depois que ele tinha comido, saiu."),("Before he left, he {{had called}} her.","Antes de partir, ele tinha ligado para ela."),("Before he moved, he {{had worked}} on a farm.","Antes de se mudar, ele tinha trabalhado numa fazenda."),("She didn't know the truth {{until}} later.","Ela só soube a verdade mais tarde.")],"Complete: “After she ___ dinner, she watched TV.”",["had cooked","has cooked","was cooking"],0,"Ação concluída antes: had cooked."),
82004:("Viradas na história","Palavras de virada: **suddenly, just as, then, at that moment**.",[("{{Just as}} she opened the door, a stranger appeared.","Assim que ela abriu a porta, um estranho apareceu."),("{{Suddenly}}, everything changed.","De repente, tudo mudou."),("{{Then}}, the stranger began to talk.","Então, o estranho começou a falar."),("{{At that moment}}, nobody moved.","Naquele momento, ninguém se mexeu.")],"“Just as” indica…",["algo ao mesmo tempo","algo muito depois","algo antes"],0,"Just as = no mesmo instante."),
82005:("used to / would","**Used to** e **would** falam de hábitos do passado; só *used to* serve para estados.",[("I {{used to live}} in a village.","Eu morava numa vila."),("We {{would play}} in the meadow.","Costumávamos brincar no prado."),("I {{didn't use to}} have a TV.","Eu não tinha TV."),("Grandma {{would bake}} bread every harvest.","A vovó fazia pão toda colheita.")],"Qual frase NÃO aceita would?",["We would walk to school.","I would live in a cottage.","She would visit us."],1,"Estado (morar): só used to."),
930001:("get over / get through","**Get over** = superar; **get through** = atravessar; **get away with** = escapar impune; **get around to** = arranjar tempo.",[("I can {{get over}} the problem.","Consigo superar o problema."),("He {{got through}} the week.","Ele atravessou a semana."),("You can't {{get away with}} cheating.","Você não escapa impune de trapacear."),("I'll {{get around to}} it soon.","Arranjo tempo para isso logo.")],"“Get over” significa…",["superar","chegar","esquecer a chave"],0,"Get over = superar."),
81275:("would: hábitos antigos","**Would + verbo** para hábitos do passado; **used to** também serve.",[("We {{would get up}} at five.","Costumávamos acordar às cinco."),("I {{used to live}} on a farm.","Eu morava numa fazenda."),("She {{would milk}} the cow every day.","Ela ordenhava a vaca todo dia."),("Mary {{always did}} her chore first.","A Mary sempre fazia a tarefa primeiro.")],"Qual é um hábito antigo?",["We would walk to school.","We walked to school yesterday.","We will walk."],0,"Would + verbo."),
82006:("Tempos da narrativa","Narrativa completa: **passado simples** (fatos), **contínuo** (cenário), **past perfect** (o que veio antes).",[("The sun {{was shining}}.","O sol brilhava."),("We {{walked}} to the beach.","Caminhamos até a praia."),("I {{had packed}} the night before.","Eu tinha arrumado as malas na noite anterior."),("It {{was}} an unforgettable moment.","Foi um momento inesquecível.")],"Qual tempo descreve o cenário?",["past simple","past continuous","past perfect"],1,"Cenário: was shining."),
82007:("Naquele momento","Passado contínuo com **at that moment / at six o'clock / this time yesterday**.",[("At six o'clock, I {{was waiting}} for the train.","Às seis, eu esperava o trem."),("While I {{was looking}} for my ticket, people {{were running}}.","Enquanto eu procurava a passagem, as pessoas corriam."),("At that moment, Sam {{found}} his ticket.","Naquele momento, o Sam achou a passagem."),("This time yesterday, we {{were flying}}.","Nesta hora ontem, estávamos voando.")],"Complete: “At nine last night I ___ TV.”",["watched","was watching","had watched"],1,"Hora marcada em andamento: contínuo."),
82008:("Perguntas no contínuo","Pergunta: **was/were + sujeito + -ing**. *What was she doing?*",[("{{What were you doing}} at nine?","O que você estava fazendo às nove?"),("{{Was he moving}} some boxes?","Ele estava mudando algumas caixas?"),("No, I {{wasn't}}. I was alone.","Não. Eu estava sozinho."),("{{Where were they going}}?","Para onde eles iam?")],"Qual pergunta está certa?",["What was she do?","What was she doing?","What she was doing?"],1,"Was + sujeito + -ing."),
82009:("Criando suspense","Cena em **past continuous**, susto em **past simple**, antecedente em **past perfect**.",[("The wind {{was blowing}} hard.","O vento soprava forte."),("{{Suddenly}}, she {{heard}} a whisper.","De repente, ela ouviu um sussurro."),("She {{hadn't slept}} all night.","Ela não tinha dormido a noite toda."),("A shadow {{was moving}} behind the curtain.","Uma sombra se movia atrás da cortina.")],"Qual verbo traz o susto?",["was blowing","heard","had slept"],1,"Fato súbito: simple."),
930002:("Collocations com make","**Make** combina com *difference, effort, progress, decision, point, plan*. Não se usa *do* nesses casos.",[("I want to {{make a difference}}.","Quero fazer a diferença."),("We {{make an effort}} with English.","Nos esforçamos com o inglês."),("He must {{make a decision}} today.","Ele precisa tomar uma decisão hoje."),("You are {{making progress}}!","Você está progredindo!")],"Qual está certa?",["do a decision","make a decision","take a decision"],1,"Make a decision."),
82010:("Conectores da história","**At first, then, but, in the end** organizam a história.",[("{{At first}}, I thought he was my friend.","No início, achei que ele era meu amigo."),("{{But then}}, I realized my mistake.","Mas então percebi meu erro."),("I {{had mixed up}} the two brothers.","Eu tinha confundido os dois irmãos."),("{{In the end}}, we laughed.","No fim, rimos.")],"“In the end” significa…",["no começo","no final","no meio"],1,"In the end = por fim."),
82011:("Expressões de tempo","Com o passado simples: **when I was nineteen, last week, two years ago**.",[("{{When I was nineteen}}, I applied for a job.","Aos dezenove anos, me candidatei a um emprego."),("They hired me {{last week}}.","Eles me contrataram na semana passada."),("I had {{no experience}}.","Eu não tinha experiência."),("I started {{two years ago}}.","Comecei há dois anos.")],"Qual está certa?",["I started since 2020.","I started in 2020.","I have started in 2020."],1,"Data definida: passado simples."),
82012:("so × because","**So** dá o resultado; **because** dá o motivo.",[("We had no map, {{so}} we got lost.","Não tínhamos mapa, então nos perdemos."),("We got lost {{because}} we had no map.","Nos perdemos porque não tínhamos mapa."),("We walked in the {{wrong direction}}.","Caminhamos na direção errada."),("It got dark, {{so}} we called for help.","Escureceu, então pedimos ajuda.")],"Qual frase dá o motivo?",["We were lost, so we called.","We called because we were lost.","We called so lost."],1,"Because + motivo."),
82013:("Past perfect na leitura","Ao ler uma carta antiga, o **past perfect** mostra o que já tinha acontecido.",[("He {{had written}} it long ago.","Ele a tinha escrito há muito tempo."),("The ink {{had faded}}.","A tinta tinha desbotado."),("He {{had promised}} to come home.","Ele tinha prometido voltar para casa."),("She {{found}} the letter in the attic.","Ela achou a carta no sótão.")],"Qual é o past perfect de “fade”?",["had faded","has faded","was fading"],0,"Had + faded."),
82014:("used to × hoje","**Used to** para o passado; **presente simples** para hoje.",[("We {{used to play}} outdoors.","Brincávamos ao ar livre."),("Now, kids {{spend}} hours on screens.","Hoje, as crianças passam horas em telas."),("My parents {{were}} strict.","Meus pais eram rígidos."),("Things {{are}} different now.","As coisas estão diferentes agora.")],"Qual marca o contraste com o passado?",["now","yesterday","ago"],0,"Now = hoje."),
930003:("call it a day","**Call it a day** = encerrar por hoje; **hit the road** = partir; **wrap up** = concluir.",[("Let's {{call it a day}}.","Vamos encerrar por hoje."),("I'll {{hit the road}} early.","Pego a estrada cedo."),("Let's {{wrap up}} the meeting.","Vamos concluir a reunião."),("We {{clocked out}} at five.","Batemos o ponto às cinco.")],"“Wrap up” significa…",["embrulhar","concluir","adiar"],1,"Wrap up = concluir."),
82015:("almost","**Almost + passado simples** = quase aconteceu.",[("We {{almost fell}} into the water.","Quase caímos na água."),("I {{almost missed}} the train.","Quase perdi o trem."),("While Sam {{was steering}}, Grace {{held}} the rope.","Enquanto o Sam conduzia, a Grace segurava a corda."),("It {{was}} a narrow escape.","Foi por pouco.")],"“I almost fell” significa…",["Caí.","Quase caí.","Vou cair."],1,"Almost = por pouco."),
82016:("Recontar uma história","Sequência: **first, then, after that, finally**.",[("{{Once upon a time}}, a queen lived in a castle.","Era uma vez uma rainha que vivia num castelo."),("{{Then}}, the queen became jealous.","Então, a rainha ficou com ciúmes."),("{{After that}}, she fell asleep.","Depois disso, ela adormeceu."),("{{Finally}}, a prince arrived.","Por fim, um príncipe chegou.")],"Qual vem depois de “then”?",["first","after that","once upon a time"],1,"Sequência."),
82017:("Mistério","Fatos (**simple**), cenário (**continuous**), antecedente (**past perfect**).",[("I {{heard}} a strange noise.","Ouvi um barulho estranho."),("I {{was walking}} down the hallway.","Eu andava pelo corredor."),("Someone {{had opened}} my locker.","Alguém tinha aberto meu armário."),("Who {{could}} have done it?","Quem poderia ter feito isso?")],"Complete: “When I got there, someone ___ the door.”",["had opened","was opening","opens"],0,"Já estava aberta: had opened."),
82018:("so / such / too","**So + adjetivo**, **such + substantivo**, **too** = excesso.",[("It was {{so}} late that we panicked.","Era tão tarde que entramos em pânico."),("There was {{such a}} lot of traffic.","Havia muito trânsito."),("I was {{too tired}} to run.","Estava cansado demais para correr."),("It was {{such a}} long delay.","Foi um atraso tão longo.")],"Complete: “It was ___ a long day.”",["so","such","too"],1,"Such a + substantivo."),
82019:("Contar um sonho","Conte sonhos no passado: **I was walking… when… I fell… I woke up.**",[("{{In my dream}}, I was flying.","No sonho, eu estava voando."),("{{Suddenly}}, I fell into a hole.","De repente, caí num buraco."),("{{Then}} I woke up.","Então acordei."),("The rabbit {{was}} very weird.","O coelho era muito estranho.")],"Qual é o passado de “wake”?",["waked","woke","waken"],1,"Wake → woke."),
930004:("would rather / prefer","**Would rather** + verbo base; **prefer … to …**; **would prefer to** + infinitivo.",[("I'd {{rather eat}} inside.","Prefiro comer lá dentro."),("I {{prefer}} tea {{to}} coffee.","Prefiro chá a café."),("I'd {{prefer to}} wait.","Preferiria esperar."),("I'd rather {{not}} go.","Prefiro não ir.")],"Qual está certa?",["I'd rather to stay.","I'd rather stay.","I'd rather staying."],1,"Would rather + verbo base."),
82020:("Narrar a partida","Fatos (**simple**) e o que já tinha acontecido (**past perfect**).",[("Sam {{scored}} in the last minute.","O Sam marcou no último minuto."),("By halftime, we {{had scored}} once.","No intervalo, tínhamos marcado uma vez."),("The crowd {{went wild}}.","A torcida enlouqueceu."),("The opponent {{had played}} well.","O adversário tinha jogado bem.")],"“By halftime” aponta para…",["antes do intervalo","depois do jogo","amanhã"],0,"By + tempo = até lá."),
82021:("Passivo no passado","**Was/were + particípio**: *The diary was published in 1947.*",[("The diary {{was published}} in 1947.","O diário foi publicado em 1947."),("They {{were discovered}} in 1944.","Eles foram descobertos em 1944."),("{{When was}} the diary {{published}}?","Quando o diário foi publicado?"),("The family {{was hidden}} for two years.","A família ficou escondida por dois anos.")],"Qual está no passivo?",["They discovered it.","It was discovered.","It discovers."],1,"Was + particípio."),
82022:("Etapas da viagem","**First, next, after that, by the time, finally**.",[("{{First}}, we crossed the border.","Primeiro, cruzamos a fronteira."),("{{After that}}, we camped by a river.","Depois, acampamos perto de um rio."),("{{By the time}} we arrived, we had changed.","Quando chegamos, já tínhamos mudado."),("{{Finally}}, we reached the town.","Por fim, chegamos à cidade.")],"“By the time” introduz…",["um momento de referência","um lugar","uma pessoa"],0,"By the time = até que."),
82023:("Desculpas","Explique atrasos com **because** + past perfect: *I was late because I had forgotten…*",[("I was late {{because}} I {{had forgotten}} my alarm.","Atrasei porque tinha esquecido meu alarme."),("I'm really {{sorry}} for being late.","Sinto muito pelo atraso."),("Please be {{honest}} with me.","Por favor, seja honesto comigo."),("It wasn't my {{fault}}.","Não foi culpa minha.")],"Qual explica o motivo?",["I forgot, so I was late.","I was late because I had forgotten.","I was forgetting late."],1,"Because + had forgotten."),
930005:("make up / make out","**Make up** = fazer as pazes/inventar; **make up for** = compensar; **make out** = distinguir; **make for** = ir em direção a.",[("Let's {{make up}} after the fight.","Vamos fazer as pazes depois da briga."),("I'll {{make up for}} the mistake.","Vou compensar o erro."),("I can't {{make out}} the words.","Não consigo distinguir as palavras."),("He is {{making for}} the exit.","Ele segue para a saída.")],"“Make up for” significa…",["compensar","maquiar","inventar"],0,"Make up for = compensar."),
82024:("used to be / would","**There used to be…** descreve o lugar; **would** conta ações repetidas.",[("{{There used to be}} a big tree.","Havia uma árvore grande."),("We {{would sit}} under it.","Sentávamos debaixo dela."),("{{Every evening}}, we would watch the sunset.","Toda noite, víamos o pôr do sol."),("The place {{was}} so peaceful.","O lugar era tão tranquilo.")],"Qual está certa?",["There use to be a farm.","There used to be a farm.","There used to being a farm."],1,"There used to be."),
82025:("Contar o que ouviu","**I heard (that)**, **apparently**, **they say** com o passado.",[("{{I heard that}} they got engaged.","Ouvi dizer que eles ficaram noivos."),("{{Apparently}}, it was a secret.","Aparentemente, era segredo."),("{{They say}} he was in love.","Dizem que ele estava apaixonado."),("I don't {{believe everything}} I hear.","Não acredito em tudo que ouço.")],"“Apparently” indica…",["certeza","algo que parece, mas não é confirmado","uma ordem"],1,"Apparently = ao que parece."),
82026:("Interrupções","Contínuo para o que acontecia; simples para a interrupção.",[("We {{were having}} dinner when someone {{knocked}}.","Estávamos jantando quando alguém bateu."),("{{Suddenly}}, someone knocked on the door.","De repente, alguém bateu à porta."),("Nobody {{had expected}} an inspector.","Ninguém esperava um inspetor."),("He {{asked}} a few questions.","Ele fez algumas perguntas.")],"Qual verbo é a interrupção?",["were having","knocked","had expected"],1,"Knocked."),
82027:("O tempo muda","Contínuo para o tempo em transformação; simples para os fatos.",[("The wind {{was getting}} stronger.","O vento ficava mais forte."),("{{Suddenly}}, lightning {{lit}} the sky.","De repente, um relâmpago iluminou o céu."),("We {{ran}} to find shelter.","Corremos para achar abrigo."),("We {{were}} soaked.","Estávamos encharcados.")],"Qual descreve uma mudança em curso?",["The wind got strong.","The wind was getting stronger.","The wind had got."],1,"Was getting."),
82028:("hadn't … for","**Past perfect** para algo que não acontecia há tempo: *We hadn't met for ten years.*",[("We {{hadn't met}} for ten years.","Não nos víamos há dez anos."),("She {{had cut}} her hair.","Ela tinha cortado o cabelo."),("I {{almost didn't recognize}} her.","Quase não a reconheci."),("We {{hugged}} for a long time.","Nos abraçamos por muito tempo.")],"Complete: “We ___ each other for years.”",["haven't seen","hadn't seen","didn't saw"],1,"Passado: hadn't seen."),
930006:("Gírias de jovens","**Lit, dope, sketchy, salty, ghost** são gírias para amigos, não para o trabalho.",[("That party was {{dope}}!","Aquela festa foi demais!"),("That guy looks {{salty}}.","Aquele cara parece irritado."),("He {{ghosted}} early.","Ele sumiu cedo."),("That place looks {{sketchy}}.","Aquele lugar parece suspeito.")],"Onde NÃO usar gírias?",["entre amigos","numa entrevista de emprego","numa festa"],1,"Contexto formal pede registro neutro."),
82029:("should have","Arrependimento: **should have + particípio**; **shouldn't have**.",[("I {{should have listened}} to him.","Eu deveria ter ouvido ele."),("I {{shouldn't have ignored}} him.","Eu não deveria tê-lo ignorado."),("It {{taught}} me a valuable lesson.","Isso me ensinou uma lição valiosa."),("I {{should have}} asked for advice.","Eu deveria ter pedido conselho.")],"“I should have gone” significa…",["Fui.","Eu deveria ter ido (e não fui).","Vou ir."],1,"Crítica ao passado."),
82030:("Pedir o desfecho","**And then what happened? What happened next? How did it end?**",[("{{And then what happened}}?","E então, o que aconteceu?"),("{{How did the story end}}?","Como a história terminou?"),("{{I'm so curious}}!","Estou tão curioso!"),("{{What happened next}}?","O que aconteceu depois?")],"Qual pede o final?",["How did it end?","What is your name?","Where is it?"],0,"How did it end?"),
82031:("Resumir","Resuma com **first, then, as a result, in the end**, no passado.",[("{{First}}, the prince learned the truth.","Primeiro, o príncipe soube a verdade."),("{{Then}}, he planned revenge.","Então, planejou vingança."),("{{As a result}}, many people died.","Como resultado, muitas pessoas morreram."),("{{In the end}}, he lost everything.","No fim, ele perdeu tudo.")],"“As a result” indica…",["causa","consequência","tempo"],1,"Resultado."),
82032:("while / as / until","**While/as** = ao mesmo tempo; **before, after, as soon as, until** ordenam os fatos.",[("{{While}} he was working, his friends were having dinner.","Enquanto ele trabalhava, os amigos jantavam."),("{{As soon as}} he started it, it began to shake.","Assim que ele ligou, começou a tremer."),("He traveled far {{before}} he stopped.","Ele viajou longe antes de parar."),("He waited {{until}} dawn.","Esperou até o amanhecer.")],"“As soon as” significa…",["assim que","até que","enquanto"],0,"As soon as = assim que."),
82033:("Finais irônicos","O **past perfect** explica a ironia: o que cada um tinha feito antes.",[("Jim {{had sold}} his watch.","Jim tinha vendido o relógio."),("She {{had bought}} a chain for his watch.","Ela tinha comprado uma corrente para o relógio dele."),("They {{realized}} that love was more important.","Perceberam que o amor era mais importante."),("It was {{ironic}}.","Era irônico.")],"Complete: “She ___ her hair before he bought the combs.”",["has sold","had sold","was selling"],1,"Antes: had sold."),
930007:("Marcadores de discurso","**Anyway** retoma; **by the way** acrescenta; **speaking of** conecta; **to be honest** abre sinceridade.",[("{{Anyway}}, I was saying…","Enfim, eu estava dizendo…"),("{{By the way}}, did you call him?","A propósito, você ligou para ele?"),("{{Speaking of}} music, I have tickets.","Falando em música, tenho ingressos."),("{{To be honest}}, I'm tired.","Para ser sincero, estou cansado.")],"Qual retoma o assunto?",["By the way","Anyway","To be honest"],1,"Anyway."),
82034:("for / since","**Present perfect** com **for** (período) e **since** (ponto de partida).",[("I {{haven't seen}} you {{in ages}}.","Não vejo você há séculos."),("We {{haven't spoken since}} June.","Não nos falamos desde junho."),("What {{have you been doing}} lately?","O que você tem feito ultimamente?"),("I've waited {{for}} an hour.","Esperei por uma hora.")],"Complete: “We haven't met ___ 2019.”",["for","since","ago"],1,"Ponto de partida: since."),
82035:("How long have you…?","Duração: **How long have/has + sujeito + particípio?** Resposta com **for/since**.",[("{{How long have you lived}} here?","Há quanto tempo você mora aqui?"),("{{How long has he been}} in prison?","Há quanto tempo ele está preso?"),("{{For}} almost a decade.","Por quase uma década."),("{{Since}} 2015.","Desde 2015.")],"Qual responde “How long?”",["Yesterday.","For ten years.","At ten."],1,"Duração: for."),
82036:("Simples × contínuo","**Have done** foca o resultado; **have been doing** foca a atividade.",[("He {{has solved}} several mysteries.","Ele resolveu vários mistérios."),("He {{has been working}} since Monday.","Ele trabalha desde segunda."),("I {{have just finished}} my article.","Acabei de terminar meu artigo."),("I {{have been writing}} all day.","Escrevo o dia todo.")],"Qual foca a atividade?",["I have written three reports.","I have been writing all day.","I wrote it."],1,"Have been + -ing."),
82037:("Vida até agora","Experiências sem data: **present perfect**.",[("I {{have traveled}} to ten countries.","Viajei para dez países."),("She {{has built}} a good career.","Ela construiu uma boa carreira."),("I {{haven't done}} everything yet.","Ainda não fiz tudo."),("I {{have learned}} a lot.","Aprendi muito.")],"Qual é o particípio de “build”?",["builded","built","build"],1,"Build, built, built."),
82038:("recently / lately","**Recently, lately, these days** com present perfect para mudanças que continuam.",[("{{Recently}}, prices {{have gone up}}.","Recentemente, os preços subiram."),("Many people {{have lost}} their jobs.","Muita gente perdeu o emprego."),("Things {{have started}} to improve.","As coisas começaram a melhorar."),("{{Lately}}, I {{have noticed}} changes.","Ultimamente, notei mudanças.")],"Complete: “Prices ___ lately.”",["rose","have risen","were rising"],1,"Lately + present perfect."),
930008:("collocations com take","**Take place, take part, take a risk, take advantage of, take care of**.",[("The race {{takes place}} in May.","A corrida acontece em maio."),("We {{take part}} in the contest.","Participamos do concurso."),("Don't {{take a risk}}.","Não corra riscos."),("{{Take advantage of}} the chance.","Aproveite a oportunidade.")],"“Take place” significa…",["acontecer","levar um lugar","pegar"],0,"Take place = ocorrer."),
82039:("already / yet / still","**Already** (afirmativa); **yet** (negativa/pergunta); **still** = continua.",[("We have {{already}} checked the tank.","Já conferimos o tanque."),("We haven't solved it {{yet}}.","Ainda não resolvemos."),("Have you finished {{yet}}?","Você já terminou?"),("I'm {{still}} working.","Ainda estou trabalhando.")],"“I'm still waiting” quer dizer…",["Já parei.","Continuo esperando.","Nunca esperei."],1,"Still = continua."),
82040:("first time","**This is the first time I have + particípio** ou **I have never + particípio**.",[("{{This is the first time}} I have visited Rome.","É a primeira vez que visito Roma."),("I {{have never eaten}} this before.","Nunca comi isto antes."),("It's the best meal I {{have ever had}}.","É a melhor refeição que já tive."),("It's {{the first time}} I've tried pasta here.","É a primeira vez que provo massa aqui.")],"Qual está certa?",["This is the first time I visit.","This is the first time I have visited.","This is the first time I visited."],1,"First time + present perfect."),
82041:("have just","**Have/has just + particípio** = acabou de.",[("I {{have just arrived}} at the airport.","Acabei de chegar ao aeroporto."),("The plane {{has just landed}}.","O avião acabou de pousar."),("They arrived {{five minutes ago}}.","Eles chegaram há cinco minutos."),("I {{have just}} seen my passport.","Acabei de ver meu passaporte.")],"Qual combina com “ago”?",["I have arrived five minutes ago.","I arrived five minutes ago.","I have just arrived ago."],1,"Com ago: simple past."),
82042:("Present perfect + resultado","Para algo que sumiu: **has gone missing**. *Have you seen…?*",[("My boot {{has gone missing}}.","Minha bota sumiu."),("{{Have you seen}} my boot?","Você viu minha bota?"),("I {{haven't seen}} it.","Não a vi."),("Someone {{has reported}} it.","Alguém denunciou o sumiço.")],"Qual é o particípio de “see”?",["saw","seen","seed"],1,"See, saw, seen."),
82043:("Present perfect × passado","**Present perfect** = sem momento definido; **passado simples** = momento definido.",[("I {{have found}} an old sled.","Encontrei um trenó velho."),("I {{found}} it yesterday.","Encontrei-o ontem."),("{{Has}} anyone {{answered}} your question?","Alguém respondeu à sua pergunta?"),("She {{lived}} here in 1990.","Ela morou aqui em 1990.")],"Qual está certa?",["I have seen him yesterday.","I saw him yesterday.","I have saw him yesterday."],1,"Yesterday: simple past."),
930009:("call off / call in","**Call off** = cancelar; **call in** = chamar; **call for** = exigir; **call on** = visitar.",[("They {{called off}} the trip.","Eles cancelaram a viagem."),("We {{called in}} a doctor.","Chamamos um médico."),("I'll {{call on}} the bride.","Vou visitar a noiva."),("The situation {{calls for}} action.","A situação exige ação.")],"“Call off” significa…",["cancelar","ligar","visitar"],0,"Call off = cancelar."),
82044:("Never / ever","**Never** = nunca; **ever** = alguma vez (perguntas).",[("I {{have never eaten}} a snail.","Nunca comi caracol."),("{{Have you ever sung}} in public?","Você já cantou em público?"),("Yes, I {{have}}.","Sim, já."),("{{Never have I}} seen that.","Nunca vi isso.")],"Qual é a pergunta certa?",["Did you ever sing?","Have you ever sung?","Have you ever sing?"],1,"Have + particípio."),
82045:("Mudanças","**Present perfect** para mudanças com resultado hoje.",[("He {{has become}} very wealthy.","Ele ficou muito rico."),("The city {{has grown}} a lot.","A cidade cresceu muito."),("You {{have changed}} so much.","Você mudou tanto."),("Things {{have become}} different.","As coisas ficaram diferentes.")],"Qual é o particípio de “become”?",["became","become","becomed"],1,"Become, became, become."),
}
